+      retryMaxRetries: parseInt(process.env.RETRY_MAX_RETRIES || "3", 10),
+      retryDelayMs: parseInt(process.env.RETRY_DELAY_MS || "1000", 10),
+      logLevel: (process.env.AZURE_LOG_LEVEL as any) || "info",
+    };
+  }
+
