+
+    await blockBlobClient.upload(buffer, buffer.length, {
+      conditions: {
+        leaseId,
+      },
+      blobHTTPHeaders: {
+        blobContentType: options?.contentType || "application/octet-stream",
+      },
+      metadata: options?.metadata,
+      tags: options?.tags,
+    });
+
+    console.log(`✓ Upload with lease complete: ${blobName}`);
+  }
