+  /**
+   * Gets blob properties including metadata and tags.
+   * 
+   * @param blobName - Name of the blob
+   */
+  async getBlobProperties(blobName: string): Promise<BlobMetadata> {
+    const blobClient = this.containerClient.getBlobClient(blobName);
